text:
{
  "questions": [
    {
      "n": 1,
      "start": "Welche Richtlinien und Weisungen bestehen",
      "end": "innerhalb der Polizei Basel-Landschaft, um Mobbing"
    },
    {
      "n": 2,
      "start": "Wieso wurde Anfang 2015 in der Person",
      "end": "vorweisen konnte?"
    },
    {
      "n": 3,
      "start": "Wurde Meinrad Stöcklin vor seiner Freistellung",
      "end": "Falls ja; wann und durch wen und warum?"
    },
    {
      "n": 4,
      "start": "Wurde Meinrad Stöcklin jemals von Polizeikommandant",
      "end": "angebotene?"
    },
    {
      "n": 5,
      "start": "Wurde die Sicherheitsdirektion, Meinrad Stöcklins Anstellungsbehörde,",
      "end": "hierfür dargelegt?"
    },
    {
      "n": 6,
      "start": "Falls die Frage 5 mit ja beantwortet wird: wann (Datum) und in welcher Form",
      "end": "geteilt die Sicherheitsdirektion die Sichtweise des Polizeikommandanten?"
    },
    {
      "n": 7,
      "start": "Es kursieren Gerüchte, dass man Meinrad Stöcklin eine „Offerte“ unterbreitete,",
      "end": "abfedern sollte? Stimmt dies?"
    },
    {
      "n": 8,
      "start": "Falls die Frage 7 mit ja beantwortet wird: in welcher Höhe wird hier der Steuerzahler",
      "end": "gebeten?"
    },
    {
      "n": 9,
      "start": "Falls die Frage 7 mit ja beantwortet wird: wurde Meinrad Stöcklin damit von Polizeikommandant",
      "end": "erfüllt?"
    },
    {
      "n": 10,
      "start": "Gemäss einem Bericht der Basler Zeitung vom 05.10.2016 verschickte der Polizeikommandant an",
      "end": "begründete?"
    },
    {
      "n": 11,
      "start": "Falls Frage 10 mit ja beantwortet wird: kennt die Anstellungsbehörde von Meinrad Stöcklin",
      "end": "dieses? War dieses Mail mit der Anstellungsbehörde abgesprochen?"
    },
    {
      "n": 12,
      "start": "Hat die Anstellungsbehörde etwas unternommen, um die Freistellung von Meinrad Stöcklin durch",
      "end": "rückgängig zu machen?"
    },
    {
      "n": 13,
      "start": "Wann wurde Regierungsrat Isaac Reber über all diese Vorgänge erstmals informiert und von",
      "end": "?"
    },
    {
      "n": 14,
      "start": "Ist der „Fall Meinrad Stöcklin“ bei der Polizei Basel-Landschaft ein Einzelfall oder gab es in jüngster",
      "end": "für den Steuerzahler?"
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "Wie für alle Mitarbeitenden des Kantons gilt auch für die Polizei Basel-Landschaft das",
      "end": "Mobbing und dessen Folgen“ des Personalamts."
    },
    {
      "n": 2,
      "start": null,
      "end": null
    },
    {
      "n": 3,
      "start": null,
      "end": null
    },
    {
      "n": 4,
      "start": null,
      "end": null
    },
    {
      "n": 5,
      "start": "Der Polizeikommandant informierte den Sicherheitsdirektor über die schwierige Situation und die",
      "end": "aufgetretenen Probleme im Zusammenhang mit M. Stöcklin, beispielsweise anlässlich ihrer Besprechung vom 8. August 2016."
    },
    {
      "n": 6,
      "start": "Es wird auf die Antwort zu Frage 5 verwiesen. Die Sicherheitsdirektion teilte die Einschätzung des",
      "end": "im Vordergrund stand."
    },
    {
      "n": 7,
      "start": null,
      "end": null
    },
    {
      "n": 8,
      "start": null,
      "end": null
    },
    {
      "n": 9,
      "start": null,
      "end": null
    },
    {
      "n": 10,
      "start": "Die Basler-Zeitung publizierte am 26. September 2016 einen ausführlichen Artikel über die Trennung von M. Stöcklin. Der Artikel stellte die Gründe, die zur Trennung führten, einseitig dar. Aus",
      "end": "um soweit erforderlich einseitige Darstellungen in das richtige Licht zu rücken."
    },
    {
      "n": 11,
      "start": "Die Sicherheitsdirektion und der Regierungsrat kennen das Mail des Polizeikommandanten und",
      "end": "musste dem Sicherheitsdirektor nicht zugestellt werden, bevor es versandt wurde."
    },
    {
      "n": 12,
      "start": null,
      "end": null
    },
    {
      "n": 13,
      "start": "Sicherheitsdirektor Isaac Reber wurde primär von Generalsekretär Stephan Mathis in der Zeit von",
      "end": "informiert."
    },
    {
      "n": 14,
      "start": "Im Jahr 2016 wurden 4 Trennungsvereinbarungen abgeschlossen.",
      "end": null
    }
  ],
  "submitter": "Paul Wenger",
